from pathlib import Path
from docx import Document
import zipfile
base=Path('tmp/cold_start')
for p in (base/'research').glob('*.docx'):
 d=Document(p)
 text=[]
 for block in d.iter_inner_content():
  if hasattr(block,'text'): text.append(block.text)
  else:
   for row in block.rows: text.append(' | '.join(c.text for c in row.cells))
 out=base/(p.stem+'.txt');out.write_text('\\n'.join(text))
 print(out,len(out.read_text()),'characters')
with zipfile.ZipFile('upload/GMRI_LOVE_NOTE_COLD_START_2026-10-23_FULL_WITH_SIRI_EVIDENCE(1).zip') as z:
 for f in z.infolist():
  if f.filename.startswith('siri_evidence/'):
   p=(base/f.filename).resolve()
   if not p.is_relative_to(base.resolve()): raise ValueError('Unsafe path')
   z.extract(f,base)
import fitz
for p in [*Path('project_sources').glob('*.pdf'),*(base/'siri_evidence').glob('*.pdf')]:
 d=fitz.open(p); out=base/(p.stem+'.txt');out.write_text('\\n'.join(f'PAGE {i+1}\\n'+page.get_text() for i,page in enumerate(d)))
 print(p.name,len(d),'pages',len(out.read_text()),'text characters')
PY"

